"""Flask dashboard for viewing and triaging alerts generated by the
detection pipeline (run_pipeline.py). Read/update only — the dashboard
itself does not run detections; it visualizes whatever is in the DB.
"""

import json

from flask import Flask, render_template, request, redirect, url_for, jsonify

import config
from storage import db

app = Flask(__name__)


@app.route("/")
def dashboard():
    db.init_db()
    stats = db.get_stats()
    recent_alerts = db.get_alerts(limit=10)
    for a in recent_alerts:
        a["evidence"] = json.loads(a["evidence"]) if a["evidence"] else {}
    return render_template("dashboard.html", stats=stats, recent_alerts=recent_alerts)


@app.route("/alerts")
def alerts():
    db.init_db()
    status = request.args.get("status") or None
    severity = request.args.get("severity") or None
    alert_list = db.get_alerts(status=status, severity=severity, limit=500)
    for a in alert_list:
        a["evidence"] = json.loads(a["evidence"]) if a["evidence"] else {}
    return render_template(
        "alerts.html",
        alerts=alert_list,
        current_status=status or "",
        current_severity=severity or "",
        severities=config.SEVERITY_ORDER,
    )


@app.route("/alerts/<int:alert_id>/status", methods=["POST"])
def update_status(alert_id):
    new_status = request.form.get("status", "open")
    db.update_alert_status(alert_id, new_status)
    return redirect(request.referrer or url_for("alerts"))


@app.route("/api/stats")
def api_stats():
    db.init_db()
    return jsonify(db.get_stats())


if __name__ == "__main__":
    db.init_db()
    app.run(debug=True, host="0.0.0.0", port=5000)
